import { useEffect, useMemo, useState } from "react";
import { FluentProvider } from "@fluentui/react-components";
import { ja } from "./strings/ja";
import { hsLightTheme, hsDarkTheme } from "./theme/fluentTheme";
import { useThemeMode } from "./theme/useThemeMode";
import { AppShell } from "./components/AppShell";
import { TitleBar } from "./components/TitleBar";
import { CommandBar } from "./components/CommandBar";
import { WaveformView } from "./components/WaveformView";
import { ScoreWorkspace } from "./components/ScoreWorkspace";
import { PropertiesPanel } from "./components/PropertiesPanel";
import { TransportBar } from "./components/TransportBar";
import { StatusBar } from "./components/StatusBar";
import { SettingsView } from "./components/SettingsView";
import type { PitchView } from "./components/PitchSegmented";
import {
  createCommands,
  dispatchCommand,
  type CommandContext,
} from "./commands/registry";
import { getShellInfo } from "./tauri/bridge";

type View = "workspace" | "settings";

/**
 * UI-001 spike shell. Screen state is fixed to EMPTY (GUI_UX_SPEC §27):
 * no audio, no score, no engine. The shell proves layout, theming,
 * Japanese copy, keyboard focus, IPC plumbing and the CSP/capability
 * baseline before real features are wired in.
 */
export default function App() {
  const { mode, resolved, select } = useThemeMode();
  const [view, setView] = useState<View>("workspace");
  const [pitch, setPitch] = useState<PitchView>("concert");
  const [statusMessage, setStatusMessage] = useState<string>(ja.status.ready);
  const [shellDetail, setShellDetail] = useState<string | undefined>(
    ja.status.shellInfoLoading,
  );

  // EMPTY state: nothing loaded yet.
  const shellState = useMemo(
    () => ({ hasAudio: false, hasScore: false, reviewCount: 0 }),
    [],
  );
  const commands = useMemo(() => createCommands(shellState), [shellState]);

  const ctx = useMemo<CommandContext>(
    () => ({
      setPitchView: setPitch,
      openAudioRequested: () => setStatusMessage(ja.status.spikeNoFileOpen),
      openSettings: () => setView("settings"),
    }),
    [],
  );

  // Central shortcut dispatch (GUI_UX_SPEC §23).
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (dispatchCommand(e, commands, ctx)) e.preventDefault();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [commands, ctx]);

  // Prove the JS↔Rust IPC channel early; populates the status area.
  useEffect(() => {
    let alive = true;
    getShellInfo().then((info) => {
      if (!alive) return;
      setShellDetail(
        info ? `v${info.version}` : undefined, // browser dev: no shell info
      );
      setStatusMessage(ja.status.ready);
    });
    return () => {
      alive = false;
    };
  }, []);

  const theme = resolved === "dark" ? hsDarkTheme : hsLightTheme;

  return (
    <FluentProvider theme={theme}>
      <AppShell>
        <TitleBar />
        {view === "settings" ? (
          <div className="hs-settings-wrap">
            <SettingsView
              themeMode={mode}
              onThemeMode={select}
              onBack={() => setView("workspace")}
            />
          </div>
        ) : (
          <>
            <CommandBar
              commands={commands}
              ctx={ctx}
              pitch={pitch}
              onPitch={setPitch}
            />
            <WaveformView />
            <div className="hs-main">
              <ScoreWorkspace onOpenAudio={ctx.openAudioRequested} />
              <PropertiesPanel />
            </div>
            <TransportBar enabled={shellState.hasAudio} />
          </>
        )}
        <StatusBar message={statusMessage} detail={shellDetail} />
      </AppShell>
    </FluentProvider>
  );
}

/**
 * Keyboard command registry (docs/GUI_UX_SPEC.md §23).
 *
 * All shortcuts are defined in this single place; components must not
 * register their own ad-hoc keydown handlers for app commands.
 */

export interface CommandContext {
  setPitchView(view: "concert" | "hornF"): void;
  openAudioRequested(): void;
  openSettings(): void;
}

export interface Command {
  id: string;
  /** Japanese label shown in UI / tooltips. */
  labelJa: string;
  /** e.g. "Ctrl+1" — matched case-insensitively on KeyboardEvent. */
  shortcut?: string;
  isEnabled(): boolean;
  execute(ctx: CommandContext): void;
}

export interface ShellState {
  hasAudio: boolean;
  hasScore: boolean;
  reviewCount: number;
}

export function createCommands(state: ShellState): Command[] {
  return [
    {
      id: "file.openAudio",
      labelJa: "音声ファイルを開く",
      shortcut: "Ctrl+O",
      isEnabled: () => true,
      execute: (ctx) => ctx.openAudioRequested(),
    },
    {
      id: "score.transcribe",
      labelJa: "採譜",
      isEnabled: () => state.hasAudio,
      execute: () => undefined, // spike: transcription engine not wired yet
    },
    {
      id: "view.concertPitch",
      labelJa: "コンサートピッチ",
      shortcut: "Ctrl+1",
      isEnabled: () => true,
      execute: (ctx) => ctx.setPitchView("concert"),
    },
    {
      id: "view.hornF",
      labelJa: "F管ホルン",
      shortcut: "Ctrl+2",
      isEnabled: () => true,
      execute: (ctx) => ctx.setPitchView("hornF"),
    },
    {
      id: "review.open",
      labelJa: "要確認",
      isEnabled: () => state.hasScore && state.reviewCount > 0,
      execute: () => undefined,
    },
    {
      id: "export.open",
      labelJa: "書き出し",
      isEnabled: () => state.hasScore,
      execute: () => undefined,
    },
    {
      id: "app.settings",
      labelJa: "設定",
      isEnabled: () => true,
      execute: (ctx) => ctx.openSettings(),
    },
  ];
}

/** Match a KeyboardEvent against "Ctrl+1" style shortcut strings. */
export function matchesShortcut(e: KeyboardEvent, shortcut: string): boolean {
  const parts = shortcut.split("+");
  const key = parts[parts.length - 1].toLowerCase();
  const wantCtrl = parts.includes("Ctrl");
  const wantShift = parts.includes("Shift");
  const wantAlt = parts.includes("Alt");
  return (
    e.key.toLowerCase() === key &&
    e.ctrlKey === wantCtrl &&
    e.shiftKey === wantShift &&
    e.altKey === wantAlt
  );
}

function isTextEntryTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  return (
    target.tagName === "INPUT" ||
    target.tagName === "TEXTAREA" ||
    target.isContentEditable
  );
}

/**
 * Central keydown dispatcher. Text-entry contexts are left alone so
 * shortcuts never fight Japanese IME input (MASTER_PLAN §8).
 */
export function dispatchCommand(
  e: KeyboardEvent,
  commands: Command[],
  ctx: CommandContext,
): boolean {
  if (isTextEntryTarget(e.target)) return false;
  for (const cmd of commands) {
    if (cmd.shortcut && matchesShortcut(e, cmd.shortcut)) {
      if (!cmd.isEnabled()) return true; // swallow: shortcut known but disabled
      cmd.execute(ctx);
      return true;
    }
  }
  return false;
}

