/**
 * HornScribe app shell layout + token consumers.
 * Colors come only from --hs-* semantic tokens (tokens.css).
 */

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-body);
  color: var(--hs-text-primary);
  background: var(--hs-surface-app);
  overflow: hidden;
}

/* ---- Visible keyboard focus (DESIGN_SYSTEM §16) ----
   2px+, distinct from adjacent surface; Fluent v9 components draw their own
   compatible focus ring, this guarantees the same contract for every other
   focusable region (waveform, score surface, segmented control, links). */
:focus-visible {
  outline: 2px solid var(--hs-focus);
  outline-offset: 2px;
  border-radius: var(--hs-radius-input);
}
/* Never remove the outline without a replacement. */
:focus:not(:focus-visible) {
  outline: none;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ============================ App shell ============================ */
/* GUI_UX_SPEC §2 information architecture:
   title bar → command bar → waveform → score workspace → transport → status */
.hs-shell {
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto auto;
  grid-template-areas:
    "titlebar"
    "commandbar"
    "waveform"
    "main"
    "transport"
    "statusbar";
  height: 100%;
  min-width: 0;
  background: var(--hs-surface-app);
  color: var(--hs-text-primary);
}

/* ---- Title bar area (in-app; native window chrome is kept) ---- */
.hs-titlebar {
  grid-area: titlebar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 32px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-titlebar__app {
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-titlebar__doc {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- Command bar (DESIGN_SYSTEM §10: ~44px, never scrolls) ---- */
.hs-commandbar {
  grid-area: commandbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 44px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  overflow: hidden;
  white-space: nowrap;
}
.hs-commandbar__spacer {
  flex: 1 1 auto;
  min-width: var(--hs-space-sm);
}

/* ---- Segmented control (DESIGN_SYSTEM §11: text labels, never icon-only) ---- */
.hs-segmented {
  display: inline-flex;
  flex: 0 0 auto;
  border: 1px solid var(--hs-border-strong);
  border-radius: var(--hs-radius-input);
  overflow: hidden;
  background: var(--hs-surface-elevated);
}
.hs-segmented__item {
  appearance: none;
  border: none;
  background: transparent;
  color: var(--hs-text-secondary);
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-compact);
  line-height: 1;
  padding: 8px 12px;
  cursor: pointer;
  white-space: nowrap;
}
.hs-segmented__item + .hs-segmented__item {
  border-left: 1px solid var(--hs-border-subtle);
}
.hs-segmented__item:hover {
  background: var(--hs-score-current-measure);
}
/* selected state = fill + weight + border cues combined (§11) */
.hs-segmented__item[aria-checked="true"] {
  background: var(--hs-accent);
  color: var(--hs-surface-score);
  font-weight: 600;
  box-shadow: inset 0 0 0 1px var(--hs-accent-pressed);
}
.hs-segmented__item:focus-visible {
  outline-offset: -2px;
}

/* ---- Waveform region (GUI_UX_SPEC §8: 96–120px standard) ---- */
.hs-waveform {
  grid-area: waveform;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 96px;
  min-height: 64px;
  max-height: 35vh;
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

/* ---- Score workspace + properties ---- */
.hs-main {
  grid-area: main;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 0;
  min-width: 0;
}

.hs-score {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--hs-space-md);
  min-width: 0;
  min-height: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-score);
  color: var(--hs-text-primary);
  /* Score paper keeps a hairline radius, not decorative rounding (§7). */
  border-radius: var(--hs-radius-score-paper);
  overflow: auto;
}

.hs-properties {
  width: 264px;
  min-width: 200px;
  max-width: 320px;
  padding: var(--hs-space-md);
  background: var(--hs-surface-panel);
  border-left: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-secondary);
  overflow: auto;
}
.hs-properties__title {
  margin: 0 0 var(--hs-space-sm);
  font-size: var(--hs-font-size-subtitle);
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-properties__body {
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-muted);
}

/* §21 responsive: below 1200px the panel collapses to a drawer candidate. */
@media (max-width: 1199px) {
  .hs-properties {
    display: none;
  }
}

/* ---- Empty state (GUI_UX_SPEC §3, §19: compact, clear CTA) ---- */
.hs-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--hs-space-sm);
  text-align: center;
  max-width: 46em;
}
.hs-empty__title {
  margin: 0;
  font-size: var(--hs-font-size-display);
  font-weight: 400;
}
.hs-empty__or {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}
.hs-empty__formats {
  margin: var(--hs-space-xs) 0 0;
  color: var(--hs-text-secondary);
  font-size: var(--hs-font-size-compact);
}
.hs-empty__privacy {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}

/* ---- Transport (GUI_UX_SPEC §9) ---- */
.hs-transport {
  grid-area: transport;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 52px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
}
.hs-transport__time {
  font-variant-numeric: tabular-nums; /* §5: timecode uses tabular numerals */
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  margin-left: var(--hs-space-sm);
  white-space: nowrap;
}
.hs-transport__spacer {
  flex: 1 1 auto;
}

/* ---- Status bar ---- */
.hs-statusbar {
  grid-area: statusbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-md);
  height: 26px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-caption);
  color: var(--hs-text-muted);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-statusbar__message {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hs-statusbar__spacer {
  flex: 1 1 auto;
}

/* ---- Settings (auxiliary screen, §18): replaces the workspace rows ---- */
.hs-settings-wrap {
  grid-row: commandbar / transport; /* spans commandbar…main rows */
  display: flex;
  min-height: 0;
  min-width: 0;
}
.hs-settings {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-app);
  overflow: auto;
}
.hs-settings__title {
  margin: 0 0 var(--hs-space-md);
  font-size: var(--hs-font-size-title);
  font-weight: 600;
}
.hs-settings__section {
  margin: 0 0 var(--hs-space-lg);
  padding: var(--hs-space-md);
  background: var(--hs-surface-panel);
  border: 1px solid var(--hs-border-subtle);
  border-radius: var(--hs-radius-panel);
  max-width: 560px;
}
.hs-settings__section-title {
  margin: 0 0 var(--hs-space-sm);
  font-size: var(--hs-font-size-subtitle);
  font-weight: 600;
}
.hs-settings__note {
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

import { invoke } from "@tauri-apps/api/core";

/**
 * Shell↔Rust boundary.
 *
 * App-defined commands are invoked over Tauri's built-in IPC channel and are
 * NOT governed by capabilities/ACL (those apply to plugin/core commands).
 * No plugin permissions are required for `shell_info`.
 */
export interface ShellInfo {
  appName: string;
  version: string;
  rustTargetEnv: string;
}

/**
 * Returns null instead of throwing when the app runs outside the Tauri
 * webview (e.g. plain `vite dev` in a browser) so the shell still renders.
 */
export async function getShellInfo(): Promise<ShellInfo | null> {
  try {
    return await invoke<ShellInfo>("shell_info");
  } catch {
    return null;
  }
}

import {
  createLightTheme,
  createDarkTheme,
  type BrandVariants,
  type Theme,
} from "@fluentui/react-components";

/**
 * Fluent v9 theme mapping for HornScribe (docs/DESIGN_SYSTEM.md §3).
 *
 * The brand ramp is Fluent's blue ramp: the accent deliberately tracks the
 * Windows/Fluent system feel rather than a fixed custom brand color.
 * HornScribe-specific semantics live in the --hs-* CSS tokens (tokens.css);
 * the Fluent theme below governs v9 component internals.
 */
const hornscribeBrand: BrandVariants = {
  10: "#061724",
  20: "#082338",
  30: "#0a2e4a",
  40: "#0c3b5e",
  50: "#0e4775",
  60: "#0f548c",
  70: "#115ea3",
  80: "#0f6cbd",
  90: "#2886de",
  100: "#479ef5",
  110: "#62abf5",
  120: "#77b7f7",
  130: "#96c6fa",
  140: "#b4d6fa",
  150: "#cfe4fa",
  160: "#ebf3fc",
};

export const hsLightTheme: Theme = createLightTheme(hornscribeBrand);
export const hsDarkTheme: Theme = createDarkTheme(hornscribeBrand);

export type ThemeMode = "system" | "light" | "dark";
export type ResolvedTheme = "light" | "dark";

/**
 * HornScribe semantic design tokens (docs/DESIGN_SYSTEM.md §3).
 *
 * Token layers: primitive → semantic (--hs-*) → component.
 * Components must reference --hs-* tokens, never raw hex values.
 * The raw values in THIS file are the documented §25 exception
 * (the single place where primitives are bound to semantics).
 *
 * Values are Fluent v9 neutral/brand palette aligned: the accent stays
 * consistent with Windows/Fluent instead of a fixed brand color (§3).
 */

:root {
  /* ---- Typography (DESIGN_SYSTEM §5) ---- */
  --hs-font-family:
    "Segoe UI Variable",
    "Segoe UI",
    "Yu Gothic UI",
    "Meiryo",
    sans-serif;
  --hs-font-size-caption: 12px;
  --hs-font-size-compact: 13px;
  --hs-font-size-body: 14px;
  --hs-font-size-subtitle: 16px;
  --hs-font-size-title: 20px;
  --hs-font-size-display: 24px;

  /* ---- Spacing, 4px grid (§6) ---- */
  --hs-space-micro: 2px;
  --hs-space-xs: 4px;
  --hs-space-sm: 8px;
  --hs-space-ms: 12px;
  --hs-space-md: 16px;
  --hs-space-ml: 20px;
  --hs-space-lg: 24px;
  --hs-space-xl: 32px;
  --hs-space-2xl: 48px;

  /* ---- Geometry (§7): radius is functional, not decorative ---- */
  --hs-radius-input: 6px;
  --hs-radius-panel: 8px;
  --hs-radius-modal: 10px;
  --hs-radius-score-paper: 3px;

  /* ---- Motion (§18) ---- */
  --hs-motion-fast: 100ms;
  --hs-motion-normal: 180ms;
  --hs-motion-panel: 220ms;
  --hs-motion-dialog: 240ms;
}

/* ============================= LIGHT ============================= */
