  --hs-playhead: #0c3b5e;

  --hs-score-selection: rgba(15, 108, 189, 0.25);
  --hs-score-active-note: #0f6cbd;
  --hs-score-current-measure: rgba(0, 0, 0, 0.05);
  --hs-review-marker: #986f0b;
}

/* ============================= DARK ============================== */
/* DESIGN_SYSTEM §13 option A: dark chrome + light score paper.      */
/* --hs-surface-score and the score-ink tokens intentionally stay     */
/* light so notation keeps normal readability on a dark shell.        */
[data-hs-theme="dark"] {
  --hs-surface-app: #1f1f1f;
  --hs-surface-score: #fafafa;
  --hs-surface-panel: #292929;
  --hs-surface-elevated: #383838;

  --hs-text-primary: #ffffff;
  --hs-text-secondary: #d6d6d6;
  --hs-text-muted: #adadad;
  --hs-text-disabled: #5c5c5c;

  --hs-border-subtle: #404040;
  --hs-border-strong: #adadad;

  --hs-accent: #479ef5;
  --hs-accent-hover: #62abf5;
  --hs-accent-pressed: #2886de;

  --hs-focus: #ffffff;

  --hs-status-info: #62abf5;
  --hs-status-warning: #fee06e;
  --hs-status-error: #f1707b;
  --hs-status-success: #9fd89f;

  --hs-waveform: #9eaab2;
  --hs-waveform-played: rgba(71, 158, 245, 0.8);
  --hs-waveform-selection: rgba(71, 158, 245, 0.3);
  --hs-playhead: #a6c8fa;

  /* Score marks land on the (light) score paper in both themes. */
  --hs-score-selection: rgba(15, 108, 189, 0.25);
  --hs-score-active-note: #0f6cbd;
  --hs-score-current-measure: rgba(0, 0, 0, 0.06);
  --hs-review-marker: #8a6308;
}

import { useCallback, useEffect, useMemo, useState } from "react";
import type { ResolvedTheme, ThemeMode } from "./fluentTheme";

const STORAGE_KEY = "hornscribe.theme";

function resolve(mode: ThemeMode): ResolvedTheme {
  if (mode !== "system") return mode;
  if (typeof window !== "undefined" && window.matchMedia) {
    return window.matchMedia("(prefers-color-scheme: dark)").matches
      ? "dark"
      : "light";
  }
  return "light";
}

function readInitialMode(): ThemeMode {
  try {
    const v = window.localStorage.getItem(STORAGE_KEY);
    if (v === "system" || v === "light" || v === "dark") return v;
  } catch {
    // localStorage may be unavailable under strict CSP contexts; default is fine.
  }
  return "system";
}

/**
 * light / dark / system theme selection.
 *
 * - "system" follows Windows via prefers-color-scheme (Tauri's webview
 *   exposes the OS theme through this media query) and re-resolves live.
 * - The resolved theme is published as data-hs-theme on <html> so the
 *   --hs-* semantic tokens (tokens.css) follow the same switch.
 */
export function useThemeMode() {
  const [mode, setMode] = useState<ThemeMode>(readInitialMode);
  const [systemTheme, setSystemTheme] = useState<ResolvedTheme>(() =>
    resolve("system"),
  );

  useEffect(() => {
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const onChange = () => setSystemTheme(mq.matches ? "dark" : "light");
    onChange();
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const resolved: ResolvedTheme = useMemo(
    () => (mode === "system" ? systemTheme : mode),
    [mode, systemTheme],
  );

  useEffect(() => {
    document.documentElement.dataset.hsTheme = resolved;
    document.documentElement.style.colorScheme = resolved;
  }, [resolved]);

  const select = useCallback((next: ThemeMode) => {
    setMode(next);
    try {
      window.localStorage.setItem(STORAGE_KEY, next);
    } catch {
      /* persistence is best-effort in the spike */
    }
  }, []);

  return { mode, resolved, select };
}

